pub unsafe fn calc_percentage(_ed: *mut Editor, part: i64, whole: i64) -> i32 {
    return if part > 1000000 { (part / (whole / 100)) as i32 } else { (part * 100 / whole) as i32 };
}

pub unsafe fn open_buffer(ed: *mut Editor) -> bool {
    let mut old_curbuf: bufref_T = core::mem::zeroed();
    let retval: bool = true;
    if !ml_open(ed, (*ed).curbuf) {
        close_buffer(ed, (*ed).curwin, (*ed).curbuf, 0, false, false, false);
        emsg(ed, decay(&raw mut (*ed).e_cannot_allocate_any_buffer_exiting));
        (*ed).v_dying = 2;
        getout(ed, 2);
    }
    set_bufref(ed, &raw mut old_curbuf, (*ed).curbuf);
    (*(*ed).curbuf).b_modified_was_set = false;
    (*(*ed).curwin).w_valid = 0;
    if (*(*ed).curbuf).b_flags & BF_NEVERLOADED != 0 {
        buf_init_chartab(ed, (*ed).curbuf, false);
    }
    if (*ed).got_int != 0 && !vim_strchr(ed, (*ed).p_cpo, CPO_INTMOD).is_null() || (*(*ed).curbuf).b_modified_was_set {
        changed(ed);
    } else if (retval as i32) == OK {
        unchanged(ed, (*ed).curbuf, false, true);
    }
    (*(*ed).curbuf).b_last_changedtick = (*(*ed).curbuf).b_changedtick;
    (*(*ed).curbuf).b_last_changedtick_i = (*(*ed).curbuf).b_changedtick;
    (*(*ed).curbuf).b_last_changedtick_pum = (*(*ed).curbuf).b_changedtick;
    if (*ed).got_int != 0 {
        (*(*ed).curbuf).b_flags |= BF_READERR;
    }
    if (*(*ed).curwin).w_valid & VALID_TOPLINE == 0 {
        (*(*ed).curwin).w_topline = 1;
    }
    if (retval as i32) != OK {
        return retval;
    }
    if bufref_valid(ed, &raw mut old_curbuf) && !(*old_curbuf.br_buf).b_ml.ml_root.is_null() {
        (*(*ed).curbuf).b_flags &= -7;
    }
    return retval;
}

pub unsafe fn set_bufref(ed: *mut Editor, bufref: *mut bufref_T, buf: *mut buf_T) {
    (*bufref).br_buf = buf;
    (*bufref).br_fnum = if buf.is_null() { 0 } else { (*buf).b_fnum };
    (*bufref).br_buf_free_count = (*ed).buf_free_count;
}

pub unsafe fn bufref_valid(ed: *mut Editor, bufref: *mut bufref_T) -> bool {
    return (if (*bufref).br_buf_free_count == (*ed).buf_free_count { TRUE } else { (buf_valid(ed, (*bufref).br_buf) && (*bufref).br_fnum == (*(*bufref).br_buf).b_fnum) as i32 }) != 0;
}

pub unsafe fn buf_valid(ed: *mut Editor, buf: *mut buf_T) -> bool {
    return buf == (*ed).curbuf;
}

pub unsafe fn can_unload_buffer(ed: *mut Editor, buf: *mut buf_T) -> bool {
    let mut can_unload: bool = (*buf).b_locked == 0;
    if can_unload && (*ed).updating_screen != 0 {
        if (*(*ed).curwin).w_buffer == buf {
            can_unload = false;
        }
    }
    if can_unload && (*buf).b_saving {
        can_unload = false;
    }
    if !can_unload {
        crate::host::vim_snprintf(ed, (*ed).IObuff as *mut i8, emsg_iobuff_room(ed), decay(&raw mut (*ed).e_attempt_to_delete_buffer_that_is_in_use_str), &[VArg::P(b"[No Name]\0".as_ptr() as *mut u8 as *mut c_void)]);
        emsg(ed, iobuff_or(ed, decay(&raw mut (*ed).e_attempt_to_delete_buffer_that_is_in_use_str)));
    }
    return can_unload;
}

pub unsafe fn close_buffer(ed: *mut Editor, win: *mut win_T, buf: *mut buf_T, action: i32, abort_if_last: bool, ignore_abort: bool, set_context: bool) -> bool {
    let mut bufref: bufref_T = core::mem::zeroed();
    let unload_buf: bool = action != 0;
    let wipe_buf: bool = action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE;
    let mut del_buf: bool = action == DOBUF_DEL || wipe_buf;
    let mut win_valid_2: bool = win_valid_any_tab(ed, win);
    let closed_popup: bool = !win.is_null() && !win_valid_2 && false;
    if (del_buf || wipe_buf) && !can_unload_buffer(ed, buf) {
        return false;
    }
    if set_context && win_valid_2 && (*win).w_buffer == buf {
        if (*buf).b_nwindows == 1 {
            set_last_cursor(ed, win);
        }
        buflist_setfpos(ed, buf, win, if (*win).w_cursor.lnum == 1 { 0 } else { (*win).w_cursor.lnum }, (*win).w_cursor.col, true);
    }
    set_bufref(ed, &raw mut bufref, buf);
    if (win_valid_2 || closed_popup) && (*win).w_buffer == buf && (*buf).b_nwindows == 1 {
        if abort_if_last {
            emsg(ed, decay(&raw mut (*ed).e_autocommands_caused_command_to_abort));
            return false;
        }
        win_valid_2 = win_valid_2 && win_valid_any_tab(ed, win);
    }
    let hiding_buf: bool = (*buf).b_nwindows <= 0 || (win_valid_2 || closed_popup) && (*win).w_buffer == buf && (*buf).b_nwindows == 1;
    if !hiding_buf || !unload_buf {
        return false;
    }
    del_buf = true;
    if !buf_freeall(ed, buf, (if del_buf { BFA_DEL } else { 0 }) + (if wipe_buf { BFA_WIPE } else { 0 }) + (if ignore_abort { BFA_IGNORE_ABORT } else { 0 })) {
        return false;
    }
    win_valid_2 = win_valid_2 && win_valid_any_tab(ed, win);
    if (win_valid_2 || closed_popup) && (*win).w_buffer == buf {
        (*buf).b_nwindows -= 1;
        (*win).w_buffer = null_mut();
    }
    if del_buf {
        free_buffer_stuff(ed, buf, true);
        (*buf).b_flags = 6;
        (*buf).b_p_initialized = false;
    }
    buf_clear_file(ed, buf);
    return true;
}

pub unsafe fn buf_clear_file(ed: *mut Editor, buf: *mut buf_T) {
    (*buf).b_ml.ml_line_count = 1;
    unchanged(ed, buf, true, true);
    (*buf).b_shortname = false;
    (*buf).b_ml.ml_root = null_mut();
    (*buf).b_ml.ml_flags = ML_EMPTY;
}

pub unsafe fn buf_freeall(ed: *mut Editor, buf: *mut buf_T, flags: i32) -> bool {
    let mut bufref: bufref_T = core::mem::zeroed();
    let is_curbuf: bool = buf == (*ed).curbuf;
    (*buf).b_locked += 1;
    (*buf).b_locked_split += 1;
    set_bufref(ed, &raw mut bufref, buf);
    (*buf).b_locked -= 1;
    (*buf).b_locked_split -= 1;
    if buf == (*ed).curbuf && !is_curbuf {
        return false;
    }
    if buf == (*ed).curbuf && (*ed).VIsual_active {
        end_visual_mode(ed);
    }
    ml_close(ed, buf, true);
    (*buf).b_ml.ml_line_count = 0;
    if flags & BFA_KEEP_UNDO == 0 {
        u_clearallandblockfree(ed, buf);
    }
    (*buf).b_flags &= -65;
    return true;
}

pub unsafe fn init_changedtick(_ed: *mut Editor, buf: *mut buf_T) {
    (*buf).b_changedtick = 0;
}

pub unsafe fn clear_wininfo(ed: *mut Editor, buf: *mut buf_T) {
    let mut wip: *mut wininfo_T = null_mut();
    while !(*buf).b_wininfo.is_null() {
        wip = (*buf).b_wininfo;
        (*buf).b_wininfo = (*wip).wi_next;
        free_wininfo(ed, wip);
    }
}

pub unsafe fn free_buffer_stuff(ed: *mut Editor, buf: *mut buf_T, free_options: bool) {
    if free_options {
        clear_wininfo(ed, buf);
        free_buf_options(ed, buf, true);
    }
    map_clear_mode(ed, buf, MAP_ALL_MODES, true, false);
    map_clear_mode(ed, buf, MAP_ALL_MODES, true, true);
}

pub unsafe fn free_wininfo(ed: *mut Editor, wip: *mut wininfo_T) {
    if (*wip).wi_optset {
        clear_winopt(ed, &raw mut (*wip).wi_opt);
    }
}

pub unsafe fn curbuf_reusable(ed: *mut Editor) -> bool {
    return !(*ed).curbuf.is_null() && (*(*ed).curbuf).b_nwindows <= 1 && ((*(*ed).curbuf).b_ml.ml_root.is_null() || (*(*ed).curbuf).b_ml.ml_line_count == 1 && *ml_get(ed, 1) == NUL as u8) && curbufIsChanged(ed) == 0;
}

pub unsafe fn buflist_new(ed: *mut Editor, lnum: linenr_T, flags: i32) -> *mut buf_T {
    let mut bufref: bufref_T = core::mem::zeroed();
    let mut bufref_2: bufref_T = core::mem::zeroed();
    let mut t1: i32 = 0;
    let mut buf: *mut buf_T = null_mut();
    if flags & BLN_CURBUF != 0 && curbuf_reusable(ed) {
        buf = (*ed).curbuf;
        set_bufref(ed, &raw mut bufref, buf);
        buf_freeall(ed, buf, 3);
        if !bufref_valid(ed, &raw mut bufref) {
            buf = null_mut();
        }
    }
    if buf != (*ed).curbuf || (*ed).curbuf.is_null() {
        buf = alloc_clear(ed, 4736) as *mut buf_T;
        init_changedtick(ed, buf);
    }
    clear_wininfo(ed, buf);
    (*buf).b_wininfo = alloc_clear(ed, 160) as *mut wininfo_T;
    if buf == (*ed).curbuf {
        free_buffer_stuff(ed, buf, false);
        (*buf).b_p_initialized = false;
        buf_copy_options(ed, buf, BCO_ENTER);
    } else {
        (*buf).b_fnum = { t1 = (*ed).top_file_num; (*ed).top_file_num = t1 + 1; t1 };
        if (*ed).top_file_num < 0 {
            emsg(ed, b"W14: Warning: List of file names overflow\0".as_ptr() as *mut i8);
            if (*ed).emsg_silent == 0 && !(*ed).in_assert_fails {
                out_flush(ed);
                ui_delay(ed, 3001, true);
            }
            (*ed).top_file_num = 1;
        }
        buf_copy_options(ed, buf, BCO_ALWAYS);
    }
    (*(*buf).b_wininfo).wi_fpos.lnum = lnum;
    (*(*buf).b_wininfo).wi_win = (*ed).curwin;
    (*buf).b_u_synced = true;
    (*buf).b_flags = 6;
    if flags & BLN_DUMMY != 0 {
        (*buf).b_flags |= BF_DUMMY;
    }
    buf_clear_file(ed, buf);
    clrallmarks(ed, buf);
    if flags & BLN_DUMMY == 0 {
        set_bufref(ed, &raw mut bufref_2, buf);
    }
    return buf;
}

pub unsafe fn free_buf_options(ed: *mut Editor, buf: *mut buf_T, _free_p_ff: bool) {
    clear_string_option(ed, &raw mut (*buf).b_p_mps);
    clear_string_option(ed, &raw mut (*buf).b_p_isk);
    clear_string_option(ed, &raw mut (*buf).b_p_nf);
    clear_string_option(ed, &raw mut (*buf).b_p_qe);
    (*buf).b_p_ul = -123456;
}

pub unsafe fn buflist_findnr(ed: *mut Editor, nr: i32) -> *mut buf_T {
    if !(*ed).curbuf.is_null() && (*(*ed).curbuf).b_fnum == nr {
        return (*ed).curbuf;
    }
    return null_mut();
}

pub unsafe fn buflist_setfpos(ed: *mut Editor, buf: *mut buf_T, win: *mut win_T, mut lnum: linenr_T, col: colnr_T, copy_options: bool) {
    let mut wip: *mut wininfo_T = (*buf).b_wininfo;
    while !wip.is_null() {
        if (*wip).wi_win == win {
            break;
        }
        wip = (*wip).wi_next;
    }
    if wip.is_null() {
        wip = alloc_clear(ed, 160) as *mut wininfo_T;
        (*wip).wi_win = win;
        if lnum == 0 {
            lnum = 1;
        }
    } else {
        if !(*wip).wi_prev.is_null() {
            (*(*wip).wi_prev).wi_next = (*wip).wi_next;
        } else {
            (*buf).b_wininfo = (*wip).wi_next;
        }
        if !(*wip).wi_next.is_null() {
            (*(*wip).wi_next).wi_prev = (*wip).wi_prev;
        }
        if copy_options && (*wip).wi_optset {
            clear_winopt(ed, &raw mut (*wip).wi_opt);
        }
    }
    if lnum != 0 {
        (*wip).wi_fpos.lnum = lnum;
        (*wip).wi_fpos.col = col;
    }
    if copy_options && !win.is_null() {
        copy_winopt(ed, &raw mut (*win).w_onebuf_opt, &raw mut (*wip).wi_opt);
        (*wip).wi_optset = true;
    }
    (*wip).wi_next = (*buf).b_wininfo;
    (*buf).b_wininfo = wip;
    (*wip).wi_prev = null_mut();
    if !(*wip).wi_next.is_null() {
        (*(*wip).wi_next).wi_prev = wip;
    }
}

