pub unsafe fn in_win_border(ed: *mut Editor, wp: *mut win_T, vcol: colnr_T) -> bool {
    if (*wp).w_width == 0 {
        return false;
    }
    let width1: i32 = (*wp).w_width - win_col_off(ed, wp);
    if vcol < width1 - 1 {
        return false;
    }
    if vcol == width1 - 1 {
        return true;
    }
    let width2: i32 = width1 + win_col_off2(ed, wp);
    if width2 <= 0 {
        return false;
    }
    return (vcol - width1) % width2 == width2 - 1;
}

