pub unsafe fn getvcol_nolist(ed: *mut Editor, posp: *mut pos_T) -> colnr_T {
    let mut vcol: colnr_T = 0;
    let list_save: i32 = (*(*ed).curwin).w_onebuf_opt.wo_list;
    (*(*ed).curwin).w_onebuf_opt.wo_list = FALSE;
    if (*posp).coladd != 0 {
        getvvcol(ed, (*ed).curwin, posp, null_mut(), &raw mut vcol, null_mut(), 0);
    } else {
        getvcol(ed, (*ed).curwin, posp, null_mut(), &raw mut vcol, null_mut(), 0);
    }
    (*(*ed).curwin).w_onebuf_opt.wo_list = list_save;
    return vcol;
}

pub unsafe fn getvvcol(ed: *mut Editor, wp: *mut win_T, pos: *mut pos_T, start: *mut colnr_T, cursor: *mut colnr_T, end: *mut colnr_T, flags: i32) {
    let mut col: colnr_T = 0;
    let mut coladd: colnr_T = 0;
    let mut endadd: colnr_T = 0;
    let mut ptr: *mut char_u = null_mut();
    let mut c: i32 = 0;
    if virtual_active(ed) != 0 {
        getvcol(ed, wp, pos, &raw mut col, null_mut(), null_mut(), flags);
        coladd = (*pos).coladd;
        endadd = 0;
        ptr = ml_get_buf(ed, (*wp).w_buffer, (*pos).lnum, false);
        if (*pos).col < ml_get_buf_len(ed, (*wp).w_buffer, (*pos).lnum) {
            c = utf_ptr2char(ed, ptr.wrapping_offset((*pos).col as isize));
            if c != TAB && vim_isprintc(ed, c) {
                endadd = char2cells(ed, c) - 1;
                if coladd > endadd {
                    endadd = 0;
                } else {
                    coladd = 0;
                }
            }
        }
        col += coladd;
        if !start.is_null() {
            *start = col;
        }
        if !cursor.is_null() {
            *cursor = col;
        }
        if !end.is_null() {
            *end = col + endadd;
        }
    } else {
        getvcol(ed, wp, pos, start, cursor, end, flags);
    }
}

pub unsafe fn getvcols(ed: *mut Editor, wp: *mut win_T, pos1: *mut pos_T, pos2: *mut pos_T, left: *mut colnr_T, right: *mut colnr_T, flags: i32) {
    let mut from1: colnr_T = 0;
    let mut from2: colnr_T = 0;
    let mut to1: colnr_T = 0;
    let mut to2: colnr_T = 0;
    if (if (*pos1).lnum != (*pos2).lnum { ((*pos1).lnum < (*pos2).lnum) as i32 } else { if (*pos1).col != (*pos2).col { ((*pos1).col < (*pos2).col) as i32 } else { ((*pos1).coladd < (*pos2).coladd) as i32 } }) != 0 {
        getvvcol(ed, wp, pos1, &raw mut from1, null_mut(), &raw mut to1, flags);
        getvvcol(ed, wp, pos2, &raw mut from2, null_mut(), &raw mut to2, flags);
    } else {
        getvvcol(ed, wp, pos2, &raw mut from1, null_mut(), &raw mut to1, flags);
        getvvcol(ed, wp, pos1, &raw mut from2, null_mut(), &raw mut to2, flags);
    }
    if from2 < from1 {
        *left = from2;
    } else {
        *left = from1;
    }
    if to2 > to1 {
        if *(*ed).p_sel == b'e' && from2 - 1 >= to1 {
            *right = from2 - 1;
        } else {
            *right = to2;
        }
    } else {
        *right = to1;
    }
}

pub unsafe fn skipwhite(_ed: *mut Editor, q: *mut char_u) -> *mut char_u {
    let mut p: *mut char_u = q;
    while *p == b' ' || *p == 9 {
        p = p.wrapping_add(1);
    }
    return p;
}

pub unsafe fn getwhitecols_curline(ed: *mut Editor) -> i32 {
    return getwhitecols(ed, ml_get_curline(ed));
}

pub unsafe fn getwhitecols(ed: *mut Editor, p: *mut char_u) -> i32 {
    return pdiff(skipwhite(ed, p), p) as i32;
}

pub unsafe fn skipdigits(ed: *mut Editor, q: *mut char_u) -> *mut char_u {
    let mut p: *mut char_u = q;
    while ascii_isdigit(ed, *p as i32) {
        p = p.wrapping_add(1);
    }
    return p;
}

pub unsafe fn vim_isdigit(_ed: *mut Editor, c: i32) -> bool {
    return c >= b'0' as i32 && c <= b'9' as i32;
}

pub unsafe fn vim_isxdigit(_ed: *mut Editor, c: i32) -> bool {
    return c >= b'0' as i32 && c <= b'9' as i32 || c >= b'a' as i32 && c <= b'f' as i32 || c >= b'A' as i32 && c <= b'F' as i32;
}

pub unsafe fn vim_isbdigit(_ed: *mut Editor, c: i32) -> bool {
    return c == b'0' as i32 || c == b'1' as i32;
}

pub unsafe fn vim_isodigit(_ed: *mut Editor, c: i32) -> bool {
    return c >= b'0' as i32 && c <= b'7' as i32;
}

pub unsafe fn vim_islower(ed: *mut Editor, c: i32) -> bool {
    if c <= b'@' as i32 {
        return false;
    }
    if c >= 128 {
        return utf_islower(ed, c);
    }
    return musl_islower(ed, c as u8 as i32);
}

pub unsafe fn vim_isupper(ed: *mut Editor, c: i32) -> bool {
    if c <= b'@' as i32 {
        return false;
    }
    if c >= 128 {
        return utf_isupper(ed, c);
    }
    return musl_isupper(ed, c as u8 as i32);
}

pub unsafe fn vim_toupper(ed: *mut Editor, c: i32) -> i32 {
    if c <= b'@' as i32 {
        return c;
    }
    if c >= 128 || (*ed).cmp_flags & CMP_KEEPASCII as u32 == 0 {
        return utf_toupper(ed, c);
    }
    if c < 128 && (*ed).cmp_flags & CMP_KEEPASCII as u32 != 0 {
        return if c < b'a' as i32 || c > b'z' as i32 { c } else { c - 32 };
    }
    return musl_toupper(ed, c as u8 as i32);
}

pub unsafe fn vim_tolower(ed: *mut Editor, c: i32) -> i32 {
    if c <= b'@' as i32 {
        return c;
    }
    if c >= 128 || (*ed).cmp_flags & CMP_KEEPASCII as u32 == 0 {
        return utf_tolower(ed, c);
    }
    if c < 128 && (*ed).cmp_flags & CMP_KEEPASCII as u32 != 0 {
        return if c < b'A' as i32 || c > b'Z' as i32 { c } else { c + 32 };
    }
    return musl_tolower(ed, c as u8 as i32);
}

pub unsafe fn skiptowhite(_ed: *mut Editor, mut p: *mut char_u) -> *mut char_u {
    while *p != b' ' && *p != 9 && *p != NUL as u8 {
        p = p.wrapping_add(1);
    }
    return p;
}

pub unsafe fn getdigits(ed: *mut Editor, pp: *mut *mut char_u) -> i64 {
    let mut p: *mut char_u = *pp;
    let retval: i64 = musl_strtol(ed, p as *mut i8, null_mut(), 10);
    if *p == b'-' {
        p = p.wrapping_add(1);
    }
    p = skipdigits(ed, p);
    *pp = p;
    return retval;
}

pub unsafe fn getdigits_quoted(ed: *mut Editor, pp: *mut *mut char_u) -> i64 {
    let mut p: *mut char_u = *pp;
    let mut retval: i64 = 0;
    if *p == b'-' {
        p = p.wrapping_add(1);
    }
    while ascii_isdigit(ed, *p as i32) {
        if retval >= 922337203685477570 {
            retval = LONG_MAX;
        } else {
            retval = retval * 10 - b'0' as i64 + *p as i64;
        }
        p = p.wrapping_add(1);
    }
    if *(*pp) == b'-' {
        if retval == LONG_MAX {
            retval = LONG_MIN;
        } else {
            retval = -retval;
        }
    }
    *pp = p;
    return retval;
}

