pub unsafe fn redraw_later(ed: *mut Editor, type_: i32) {
    redraw_win_later(ed, (*ed).curwin, type_);
}

pub unsafe fn redraw_win_later(ed: *mut Editor, wp: *mut win_T, type_: i32) {
    if !(*ed).exiting && !(*ed).redraw_not_allowed && (*wp).w_redr_type < type_ {
        (*wp).w_redr_type = type_;
        if type_ >= UPD_NOT_VALID {
            (*wp).w_lines_valid = 0;
        }
        if (*ed).must_redraw < type_ {
            (*ed).must_redraw = type_;
        }
    }
}

pub unsafe fn redraw_later_clear(ed: *mut Editor) {
    redraw_all_later(ed, UPD_CLEAR);
    reset_screen_attr(ed);
}

pub unsafe fn redraw_all_later(ed: *mut Editor, type_: i32) {
    let wp: *mut win_T = (*ed).curwin;
    redraw_win_later(ed, wp, type_);
    set_must_redraw(ed, type_);
}

pub unsafe fn set_must_redraw(ed: *mut Editor, type_: i32) {
    if !(*ed).redraw_not_allowed && (*ed).must_redraw < type_ {
        (*ed).must_redraw = type_;
    }
}

pub unsafe fn redraw_curbuf_later(ed: *mut Editor, type_: i32) {
    redraw_buf_later(ed, (*ed).curbuf, type_);
}

pub unsafe fn redraw_buf_later(ed: *mut Editor, buf: *mut buf_T, type_: i32) {
    let wp: *mut win_T = (*ed).curwin;
    if (*wp).w_buffer == buf {
        redraw_win_later(ed, wp, type_);
    }
}

pub unsafe fn ruler_redraw_lastwin(ed: *mut Editor) {
    if (*ed).p_ru != 0 && (*(*ed).curwin).w_status_height == 0 {
        (*ed).redraw_cmdline = TRUE;
    }
}

pub unsafe fn status_redraw_all(ed: *mut Editor) {
    let wp: *mut win_T = (*ed).curwin;
    if (*wp).w_status_height != 0 {
        (*wp).w_redr_status = true;
        redraw_later(ed, UPD_VALID);
    }
    ruler_redraw_lastwin(ed);
}

pub unsafe fn status_redraw_curbuf(ed: *mut Editor) {
    let wp: *mut win_T = (*ed).curwin;
    if (*wp).w_status_height != 0 && (*wp).w_buffer == (*ed).curbuf {
        (*wp).w_redr_status = true;
        redraw_later(ed, UPD_VALID);
    }
    if (*(*ed).curwin).w_buffer == (*ed).curbuf {
        ruler_redraw_lastwin(ed);
    }
}

pub unsafe fn redraw_statuslines(ed: *mut Editor) {
    let mut ret: bool = false;
    let wp: *mut win_T = (*ed).curwin;
    if (*wp).w_redr_status {
        ret = push_highlight_overrides(ed, (*wp).w_hl, (*wp).w_hl_len);
        win_redr_status(ed, wp, false);
        if ret {
            pop_highlight_overrides(ed);
        }
    }
    if (*ed).redraw_tabline {
        draw_tabline(ed);
    }
}

pub unsafe fn redrawWinline(ed: *mut Editor, wp: *mut win_T, lnum: linenr_T) {
    redraw_win_range_later(ed, wp, lnum, lnum);
}

pub unsafe fn redraw_win_range_later(ed: *mut Editor, wp: *mut win_T, first: linenr_T, last: linenr_T) {
    if last >= (*wp).w_topline && first < (*wp).w_botline {
        if (*wp).w_redraw_top == 0 || (*wp).w_redraw_top > first {
            (*wp).w_redraw_top = first;
        }
        if (*wp).w_redraw_bot == 0 || (*wp).w_redraw_bot < last {
            (*wp).w_redraw_bot = last;
        }
        redraw_win_later(ed, wp, UPD_VALID);
    }
}

pub unsafe fn edit_esc(ed: *mut Editor, count: *mut i64, cmdchar: i32, nomove: bool, o_lnum: *mut linenr_T) -> bool {
    if (*ed).ins_at_eol && gchar_cursor(ed) == NUL {
        *o_lnum = (*(*ed).curwin).w_cursor.lnum;
    }
    if ins_esc(ed, count, cmdchar, nomove) {
        (*ed).did_cursorhold = false;
        if !char_avail(ed) && (*(*ed).curbuf).b_last_changedtick_i == (*(*ed).curbuf).b_changedtick {
            (*(*ed).curbuf).b_last_changedtick = (*(*ed).curbuf).b_changedtick;
        }
        return true;
    }
    return false;
}

pub unsafe fn edit_normalchar(ed: *mut Editor, c: i32, mut inserted_space: bool) -> bool {
    ins_try_si(ed, c);
    if c == b' ' as i32 {
        inserted_space = true;
    }
    if vim_iswordc(ed, c) || c != Ctrl_RSB {
        insert_special(ed, c, false, false);
    }
    return inserted_space;
}

