pub unsafe fn bracketed_paste(ed: *mut Editor, mode: paste_mode_T, drop_: bool, gap: *mut garray_T) -> i32 {
    let mut c: i32 = 0;
    let mut buf: [char_u; 86] = core::mem::zeroed();
    let mut idx: i32 = 0;
    let mut end: *mut char_u = find_termcode(ed, b"PE\0".as_ptr() as *mut u8);
    let mut ret_char: i32 = -1;
    let save_allow_keys: i32 = (*ed).allow_keys;
    let save_paste: i32 = (*ed).p_paste;
    if !end.is_null() && musl_strlen(ed, end as *mut i8) >= NUMBUFLEN as u64 {
        end = null_mut();
    }
    (*ed).no_mapping += 1;
    (*ed).allow_keys = 0;
    if (*ed).p_paste == 0 {
        set_option_value_give_err(ed, b"paste\0".as_ptr() as *mut u8, TRUE as i64, null_mut(), 0);
    }
    loop {
        if end.is_null() && vpeekc(ed) == NUL {
            break;
        }
        loop {
            c = vgetc(ed);
            if !(c == K_IGNORE || c == -22777 || c == -22776) {
                break;
            }
        }
        if c == NUL || (*ed).got_int != 0 || (*ed).ex_normal_busy > 0 && c == Ctrl_C {
            break;
        }
        idx += utf_char2bytes(ed, c, decay(&raw mut buf).wrapping_offset(idx as isize));
        *decay(&raw mut buf).wrapping_offset(idx as isize) = NUL as u8;
        if !end.is_null() && musl_strncmp(ed, decay(&raw mut buf) as *mut i8, end as *mut i8, idx as u64) == 0 {
            if *end.wrapping_offset(idx as isize) == NUL as u8 {
                break;
            }
            continue;
        }
        if !drop_ {
            match mode {
                1 => {
                    put_on_cmdline(ed, decay(&raw mut buf), idx, true);
                }
                2 => {
                    if !gap.is_null() && ga_grow(ed, gap, idx + 1) {
                        musl_memmove(ed, ((*gap).ga_data as *mut i8).wrapping_offset((*gap).ga_len as isize) as *mut c_void, decay(&raw mut buf) as *mut c_void, idx as u64);
                        (*gap).ga_len += idx;
                    }
                }
                0 => {
                    if stop_arrow(ed) {
                        c = *decay(&raw mut buf) as i32;
                        if idx == 1 && (c == CAR || c == K_KENTER || c == NL) {
                            ins_eol(ed, c);
                        } else {
                            ins_char_bytes(ed, decay(&raw mut buf), idx);
                            AppendToRedobuffLit(ed, decay(&raw mut buf), idx);
                        }
                    }
                }
                3 => {
                    if ret_char == -1 {
                        ret_char = utf_ptr2char(ed, decay(&raw mut buf));
                    }
                }
                _ => {}
            }
        }
        idx = 0;
    }
    (*ed).no_mapping -= 1;
    (*ed).allow_keys = save_allow_keys;
    if save_paste == 0 {
        set_option_value_give_err(ed, b"paste\0".as_ptr() as *mut u8, FALSE as i64, null_mut(), 0);
    }
    return ret_char;
}

pub unsafe fn ins_left(ed: *mut Editor) {
    let end_change: bool = (*ed).dont_sync_undo == FALSE;
    undisplay_dollar(ed);
    let mut tpos: pos_T = (*(*ed).curwin).w_cursor;
    if oneleft(ed) {
        start_arrow_with_change(ed, &raw mut tpos, end_change);
        if !end_change {
            AppendCharToRedobuff(ed, K_LEFT);
        }
    } else if !vim_strchr(ed, (*ed).p_ww, b'[' as i32).is_null() && (*(*ed).curwin).w_cursor.lnum > 1 {
        start_arrow(ed, &raw mut tpos);
        (*(*ed).curwin).w_cursor.lnum -= 1;
        coladvance(ed, 2147483647);
        (*(*ed).curwin).w_set_curswant = true;
    } else {
        vim_beep(ed, BO_CRSR as u32);
    }
    (*ed).dont_sync_undo = FALSE;
}

pub unsafe fn ins_home(ed: *mut Editor, c: i32) {
    undisplay_dollar(ed);
    let mut tpos: pos_T = (*(*ed).curwin).w_cursor;
    if c == K_C_HOME {
        (*(*ed).curwin).w_cursor.lnum = 1;
    }
    (*(*ed).curwin).w_cursor.col = 0;
    (*(*ed).curwin).w_cursor.coladd = 0;
    (*(*ed).curwin).w_curswant = 0;
    start_arrow(ed, &raw mut tpos);
}

pub unsafe fn ins_end(ed: *mut Editor, c: i32) {
    undisplay_dollar(ed);
    let mut tpos: pos_T = (*(*ed).curwin).w_cursor;
    if c == K_C_END {
        (*(*ed).curwin).w_cursor.lnum = (*(*ed).curbuf).b_ml.ml_line_count;
    }
    coladvance(ed, 2147483647);
    (*(*ed).curwin).w_curswant = MAXCOL;
    start_arrow(ed, &raw mut tpos);
}

