pub unsafe fn global_exe(ed: *mut Editor, cmd: *mut char_u) {
    let mut lnum: linenr_T = 0;
    let old_buf: *mut buf_T = (*ed).curbuf;
    setpcmark(ed);
    (*ed).msg_didout = TRUE;
    (*ed).sub_nsubs = 0;
    (*ed).sub_nlines = 0;
    (*ed).global_need_beginline = false;
    (*ed).global_busy = 1;
    let old_lcount: linenr_T = (*(*ed).curbuf).b_ml.ml_line_count;
    while (*ed).got_int == 0 && ({ lnum = ml_firstmarked(ed); lnum }) != 0 && (*ed).global_busy == 1 {
        global_exe_one(ed, cmd, lnum);
        ui_breakcheck(ed);
    }
    (*ed).global_busy = 0;
    if (*ed).global_need_beginline {
        beginline(ed, 5);
    } else {
        check_cursor(ed);
    }
    changed_line_abv_curs(ed);
    if (*ed).msg_col == 0 && (*ed).msg_scrolled == 0 {
        (*ed).msg_didout = FALSE;
    }
    if !do_sub_msg(ed, FALSE) && (*ed).curbuf == old_buf {
        msgmore(ed, (*(*ed).curbuf).b_ml.ml_line_count - old_lcount);
    }
}

