pub unsafe fn nv_join(ed: *mut Editor, cap: *mut cmdarg_T) {
    if (*ed).VIsual_active {
        nv_operator(ed, cap);
        return;
    }
    if checkclearop(ed, (*cap).oap) {
        return;
    }
    if (*cap).count0 <= 1 {
        (*cap).count0 = 2;
    }
    if (*(*ed).curwin).w_cursor.lnum + (*cap).count0 - 1 > (*(*ed).curbuf).b_ml.ml_line_count {
        if (*cap).count0 <= 2 {
            clearopbeep(ed, (*cap).oap);
            return;
        }
        (*cap).count0 = (*(*ed).curbuf).b_ml.ml_line_count - (*(*ed).curwin).w_cursor.lnum + 1;
    }
    prep_redo(ed, (*(*cap).oap).regname, (*cap).count0, NUL, (*cap).cmdchar, NUL, NUL, (*cap).nchar);
    do_join(ed, (*cap).count0, (*cap).nchar == NUL, true, true, true);
}

