pub unsafe fn nv_put_opt(ed: *mut Editor, cap: *mut cmdarg_T, fix_indent_2: bool) {
    let mut dir: i32 = 0;
    let mut regname: i32 = 0;
    let mut reg1: *mut yankreg_T = null_mut();
    let mut reg2: *mut yankreg_T = null_mut();
    let mut empty: i32 = FALSE;
    let mut was_visual: bool = false;
    let mut flags: i32 = 0;
    let mut keep_registers: bool = false;
    if (*(*cap).oap).op_type != OP_NOP {
        clearopbeep(ed, (*cap).oap);
        return;
    }
    if fix_indent_2 {
        dir = if (*cap).cmdchar == b']' as i32 && (*cap).nchar == b'p' as i32 { FORWARD } else { -1 };
        flags |= PUT_FIXINDENT;
    } else {
        dir = if (*cap).cmdchar == b'P' as i32 || ((*cap).cmdchar == b'g' as i32 || (*cap).cmdchar == b'z' as i32) && (*cap).nchar == b'P' as i32 { -1i32 } else { FORWARD };
    }
    prep_redo_cmd(ed, cap);
    if (*cap).cmdchar == b'g' as i32 {
        flags |= PUT_CURSEND;
    } else if (*cap).cmdchar == b'z' as i32 {
        flags |= PUT_BLOCK_INNER;
    }
    if (*ed).VIsual_active {
        was_visual = true;
        regname = (*(*cap).oap).regname;
        keep_registers = (*cap).cmdchar == b'P' as i32;
        if regname == 0 || regname == b'"' as i32 || ascii_isdigit(ed, regname) || regname == b'-' as i32 {
            reg1 = get_register(ed, regname, true);
        }
        (*cap).cmdchar = b'd' as i32;
        (*cap).nchar = NUL;
        (*(*cap).oap).regname = if keep_registers { b'_' as i32 } else { NUL };
        (*ed).msg_silent += 1;
        nv_operator(ed, cap);
        do_pending_operator(ed, cap, 0, false);
        empty = (*(*ed).curbuf).b_ml.ml_flags & ML_EMPTY;
        (*ed).msg_silent -= 1;
        (*(*cap).oap).regname = regname;
        if !reg1.is_null() {
            reg2 = get_register(ed, regname, false);
            put_register(ed, regname, reg1);
        }
        if (*ed).VIsual_mode == b'V' as i32 {
            flags |= PUT_LINE;
        } else if (*ed).VIsual_mode == b'v' as i32 {
            flags |= PUT_LINE_SPLIT;
        }
        if (*ed).VIsual_mode == Ctrl_V && dir == FORWARD {
            flags |= PUT_LINE_FORWARD;
        }
        dir = -1;
        if (*ed).VIsual_mode != b'V' as i32 && (*(*ed).curwin).w_cursor.col < (*(*ed).curbuf).b_op_start.col || (*ed).VIsual_mode == b'V' as i32 && (*(*ed).curwin).w_cursor.lnum < (*(*ed).curbuf).b_op_start.lnum {
            dir = FORWARD;
        }
        (*ed).VIsual_active = true;
    }
    do_put(ed, (*(*cap).oap).regname, null_mut(), dir, (*cap).count1, flags);
    if !reg2.is_null() {
        put_register(ed, regname, reg2);
    }
    if was_visual {
        (*(*ed).curbuf).b_visual.vi_start = (*(*ed).curbuf).b_op_start;
        (*(*ed).curbuf).b_visual.vi_end = (*(*ed).curbuf).b_op_end;
        if *(*ed).p_sel == b'e' {
            inc(ed, &raw mut (*(*ed).curbuf).b_visual.vi_end);
        }
    }
    if empty != 0 && *ml_get(ed, (*(*ed).curbuf).b_ml.ml_line_count) == NUL as u8 {
        ml_delete_flags(ed, (*(*ed).curbuf).b_ml.ml_line_count, ML_DEL_MESSAGE);
        deleted_lines(ed, (*(*ed).curbuf).b_ml.ml_line_count + 1, 1);
        if (*(*ed).curwin).w_cursor.lnum > (*(*ed).curbuf).b_ml.ml_line_count {
            (*(*ed).curwin).w_cursor.lnum = (*(*ed).curbuf).b_ml.ml_line_count;
            coladvance(ed, 2147483647);
        }
    }
}

