    let mut max_pos: pos_T = core::mem::zeroed();
    let mut oparg: oparg_T = core::mem::zeroed();
    let mut bd: block_def = core::mem::zeroed();
    let mut s: *mut char_u = null_mut();
    let mut len: i64 = 0;
    let mut start_col: colnr_T = 0;
    let mut end_col: colnr_T = 0;
