pub unsafe fn did_set_cmdheight(ed: *mut Editor, args: *mut optset_T) -> *mut i8 {
    let old_value: i64 = (*args).os_oldval.number;
    let mut errmsg: *mut i8 = null_mut();
    if (*ed).p_ch < MIN_CMDHEIGHT as i64 {
        errmsg = decay(&raw mut (*ed).e_argument_must_be_positive);
        (*ed).p_ch = MIN_CMDHEIGHT as i64;
    }
    if (*ed).p_ch > (*ed).Rows - min_rows(ed) as i64 + MIN_CMDHEIGHT as i64 {
        (*ed).p_ch = (*ed).Rows - min_rows(ed) as i64 + MIN_CMDHEIGHT as i64;
    }
    if ((*ed).p_ch != old_value || ((*(*ed).topframe).fr_height as i64) != (*ed).Rows - (*ed).p_ch) && (*ed).full_screen != 0 {
        command_height(ed);
    }
    return errmsg;
}

