pub unsafe fn did_set_global_listfillchars(ed: *mut Editor, val: *mut char_u, opt_lcs: bool, opt_flags: i32, errbuf: *mut i8, errbuflen: usize_) -> *mut i8 {
    let mut errmsg: *mut i8 = null_mut();
    let local_ptr: *mut *mut char_u = if opt_lcs { &raw mut (*(*ed).curwin).w_onebuf_opt.wo_lcs } else { &raw mut (*(*ed).curwin).w_onebuf_opt.wo_fcs };
    if opt_lcs {
        errmsg = set_listchars_option(ed, (*ed).curwin, val, *(*local_ptr) == NUL as u8 || opt_flags & OPT_GLOBAL == 0, errbuf, errbuflen);
    } else {
        errmsg = set_fillchars_option(ed, (*ed).curwin, val, *(*local_ptr) == NUL as u8 || opt_flags & OPT_GLOBAL == 0, errbuf, errbuflen);
    }
    if !errmsg.is_null() {
        return errmsg;
    }
    if opt_flags & OPT_GLOBAL == 0 {
        clear_string_option(ed, local_ptr);
    }
    let wp: *mut win_T = (*ed).curwin;
    if opt_lcs {
        if *(*wp).w_onebuf_opt.wo_lcs == NUL as u8 {
            set_listchars_option(ed, wp, (*wp).w_onebuf_opt.wo_lcs, true, null_mut(), 0);
        }
    } else {
        if *(*wp).w_onebuf_opt.wo_fcs == NUL as u8 {
            set_fillchars_option(ed, wp, (*wp).w_onebuf_opt.wo_fcs, true, null_mut(), 0);
        }
    }
    redraw_all_later(ed, UPD_NOT_VALID);
    return null_mut();
}

