pub unsafe fn did_set_term_option(ed: *mut Editor, args: *mut optset_T) -> *mut i8 {
    let mut colors: i32 = 0;
    let varp: *mut *mut char_u = (*args).os_varp.ov_str;
    if (*ed).full_screen == 0 {
        return null_mut();
    }
    if varp == decay(&raw mut (*ed).term_strings).wrapping_add(49) {
        colors = musl_atoi(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(49) as *mut i8);
        if colors != (*ed).t_colors {
            (*ed).t_colors = colors;
            if (*ed).t_colors <= 1 {
                *decay(&raw mut (*ed).term_strings).wrapping_add(49) = (*ed).empty_option;
            }
            init_highlight(ed, true, false);
        }
    }
    ttest(ed, false);
    if varp == decay(&raw mut (*ed).term_strings).wrapping_add(19) {
        out_str(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(19));
        redraw_later(ed, UPD_CLEAR);
    }
    if varp == decay(&raw mut (*ed).term_strings).wrapping_add(82) && (*ed).termcap_active {
        if *(*decay(&raw mut (*ed).term_strings).wrapping_add(82)) == NUL as u8 {
            out_str(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(83));
        } else {
            out_str(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(82));
        }
    }
    if varp == decay(&raw mut (*ed).term_strings).wrapping_add(92) || varp == decay(&raw mut (*ed).term_strings).wrapping_add(93) {
        term_set_sync_output(ed, TERM_SYNC_OUTPUT_OFF);
    }
    return null_mut();
}

