pub unsafe fn bt_regcomp(ed: *mut Editor, re: *mut regengine_T, expr: *mut char_u, re_flags: i32) -> *mut regprog_T {
    let mut reg__o: reg__out_T = core::mem::zeroed();
    let mut longest: *mut char_u = null_mut();
    let mut len: i32 = 0;
    let mut flags: i32 = 0;
    let mut scanlen: usize_ = 0;
    if expr.is_null() {
        return ({ iemsg(ed, decay(&raw mut (*ed).e_null_argument)); (*ed).rc_did_emsg = true; null_mut() }) as *mut regprog_T;
    }
    init_class_tab(ed);
    regcomp_start(ed, re, expr, re_flags);
    (*ed).regcode = decay(&raw mut (*ed).reg_calc_size_node);
    regc(ed, REGMAGIC);
    if ({ reg__o = reg(ed, re, REG_NOPAREN); reg__o.r__ }).is_null() {
        return null_mut();
    }
    let r: *mut regprog_T = alloc(ed, 48) as *mut regprog_T;
    (*r).program = alloc(ed, (*ed).regsize as u64) as *mut u8;
    (*r).re_in_use = false;
    regcomp_start(ed, re, expr, re_flags);
    (*ed).regcode = (*r).program;
    regc(ed, REGMAGIC);
    if ({ reg__o = reg(ed, re, REG_NOPAREN); flags = reg__o.flagp; reg__o.r__ }).is_null() || (*re).reg_toolong {
        if (*re).reg_toolong {
            return ({ emsg(ed, decay(&raw mut (*ed).e_pattern_too_long)); (*ed).rc_did_emsg = true; null_mut() }) as *mut regprog_T;
        }
        return null_mut();
    }
    (*r).regstart = NUL;
    (*r).reganch = 0;
    (*r).regmust = null_mut();
    (*r).regmlen = 0;
    (*r).regflags = (*ed).regflags;
    if flags & HASNL != 0 {
        (*r).regflags |= RF_HASNL as u32;
    }
    if flags & HASLOOKBH != 0 {
        (*r).regflags |= RF_LOOKBH as u32;
    }
    let mut scan: *mut char_u = (*r).program.wrapping_add(1);
    if (*regnext(ed, re, scan) as i32) == END {
        scan = scan.wrapping_add(3);
        if (*scan as i32) == BOL || (*scan as i32) == RE_BOF {
            (*r).reganch = (*r).reganch.wrapping_add(1);
            scan = regnext(ed, re, scan);
        }
        if (*scan as i32) == EXACTLY {
            (*r).regstart = utf_ptr2char(ed, scan.wrapping_add(3));
        } else if ((*scan as i32) == BOW || (*scan as i32) == EOW || (*scan as i32) == NOTHING || (*scan as i32) == 80 || (*scan as i32) == NOPEN || (*scan as i32) == 90 || (*scan as i32) == NCLOSE) && (*regnext(ed, re, scan) as i32) == EXACTLY {
            (*r).regstart = utf_ptr2char(ed, regnext(ed, re, scan).wrapping_add(3));
        }
        if (flags & SPSTART != 0 || (*scan as i32) == BOW || (*scan as i32) == EOW) && flags & HASNL == 0 {
            longest = null_mut();
            len = 0;
            while !scan.is_null() {
                if (*scan as i32) == EXACTLY {
                    scanlen = musl_strlen(ed, scan.wrapping_add(3) as *mut i8);
                    if scanlen >= len as u64 {
                        longest = scan.wrapping_add(3);
                        len = scanlen as i32;
                    }
                }
                scan = regnext(ed, re, scan);
            }
            (*r).regmust = longest;
            (*r).regmlen = len;
        }
    }
    return r;
}

pub unsafe fn coll_get_char(ed: *mut Editor) -> i32 {
    let mut t1: *mut char_u = null_mut();
    let mut nr: vimlong_T = -1;
    match *({ t1 = (*ed).regparse; (*ed).regparse = t1.wrapping_add(1); t1 }) as i32 {
        100 => {
            nr = getdecchrs(ed);
        }
        111 => {
            nr = getoctchrs(ed);
        }
        120 => {
            nr = gethexchrs(ed, 2);
        }
        117 => {
            nr = gethexchrs(ed, 4);
        }
        85 => {
            nr = gethexchrs(ed, 8);
        }
        _ => {}
    }
    if nr < 0 {
        (*ed).regparse = (*ed).regparse.wrapping_sub(1);
        nr = 92;
    }
    if nr > INT_MAX as i64 {
        nr = INT_MAX as i64;
    }
    return nr as i32;
}

pub unsafe fn bt_regfree(_ed: *mut Editor, _prog: *mut regprog_T) {
}

pub unsafe fn reg_save(_ed: *mut Editor, re: *mut regengine_T, save: *mut regsave_T, gap: *mut garray_T) {
    if (*re).rex.reg_match.is_null() {
        (*save).rs_u.pos.col = pdiff((*re).rex.input, (*re).rex.line) as i32;
        (*save).rs_u.pos.lnum = (*re).rex.lnum;
    } else {
        (*save).rs_u.ptr = (*re).rex.input;
    }
    (*save).rs_len = (*gap).ga_len;
}

pub unsafe fn reg_restore(ed: *mut Editor, re: *mut regengine_T, save: *mut regsave_T, gap: *mut garray_T) {
    if (*re).rex.reg_match.is_null() {
        if (*re).rex.lnum != (*save).rs_u.pos.lnum {
            (*re).rex.lnum = (*save).rs_u.pos.lnum;
            (*re).rex.line = reg_getline(ed, re, (*re).rex.lnum);
        }
        (*re).rex.input = (*re).rex.line.wrapping_offset((*save).rs_u.pos.col as isize);
    } else {
        (*re).rex.input = (*save).rs_u.ptr;
    }
    (*gap).ga_len = (*save).rs_len;
}

pub unsafe fn reg_save_equal(_ed: *mut Editor, re: *mut regengine_T, save: *mut regsave_T) -> bool {
    if (*re).rex.reg_match.is_null() {
        return (*re).rex.lnum == (*save).rs_u.pos.lnum && (*re).rex.input == (*re).rex.line.wrapping_offset((*save).rs_u.pos.col as isize);
    }
    return (*re).rex.input == (*save).rs_u.ptr;
}

pub unsafe fn save_se_multi(_ed: *mut Editor, re: *mut regengine_T, savep: *mut save_se_T, posp: *mut lpos_T) {
    (*savep).se_u.pos = *posp;
    (*posp).lnum = (*re).rex.lnum;
    (*posp).col = pdiff((*re).rex.input, (*re).rex.line) as i32;
}

pub unsafe fn save_se_one(_ed: *mut Editor, re: *mut regengine_T, savep: *mut save_se_T, pp: *mut *mut char_u) {
    (*savep).se_u.ptr = *pp;
    *pp = (*re).rex.input;
}

