pub unsafe fn term_font(ed: *mut Editor, n: i32) {
    let mut buf: [i8; 20] = core::mem::zeroed();
    if *(*decay(&raw mut (*ed).term_strings).wrapping_add(90)) != 0 {
        crate::host::vim_snprintf(ed, decay(&raw mut buf), 20, *decay(&raw mut (*ed).term_strings).wrapping_add(90) as *mut i8, &[VArg::I((9 + n) as i64)]);
        out_str(ed, decay(&raw mut buf) as *mut u8);
    }
}

pub unsafe fn term_color(ed: *mut Editor, s: *mut char_u, n: i32) {
    let mut buf: [i8; 20] = core::mem::zeroed();
    let mut format: *mut i8 = null_mut();
    let mut lead: *mut i8 = null_mut();
    let mut tail: *mut i8 = null_mut();
    let mut i: i32 = if *s == CSI as u8 { 1i32 } else { 2 };
    if n >= 8 && (*ed).t_colors >= 16 && (*s == ESC as u8 && *s.wrapping_add(1) == b'[' || *s == CSI as u8 && ({ i = 1; i }) == 1) && *s.wrapping_offset(i as isize) != NUL as u8 && (musl_strcmp(ed, s.wrapping_offset(i as isize).wrapping_add(1) as *mut i8, b"%p1%dm\0".as_ptr() as *mut i8) == 0 || musl_strcmp(ed, s.wrapping_offset(i as isize).wrapping_add(1) as *mut i8, b"%dm\0".as_ptr() as *mut i8) == 0) && (*s.wrapping_offset(i as isize) == b'3' || *s.wrapping_offset(i as isize) == b'4') {
        format = b"%s%s%%dm\0".as_ptr() as *mut i8;
        lead = if i == 2 { b"\x1b[\0".as_ptr() as *mut i8 } else { b"\x9b\0".as_ptr() as *mut i8 };
        tail = if *s.wrapping_offset(i as isize) == b'3' { if n >= 16 { b"38;5;\0".as_ptr() as *mut i8 } else { b"9\0".as_ptr() as *mut i8 } } else { if n >= 16 { b"48;5;\0".as_ptr() as *mut i8 } else { b"10\0".as_ptr() as *mut i8 } };
        crate::host::vim_snprintf(ed, decay(&raw mut buf), 20, format, &[VArg::P(lead as *mut c_void), VArg::P(tail as *mut c_void)]);
        out_str(ed, tgoto(ed, decay(&raw mut buf), 0, if n >= 16 { n } else { n - 8 }) as *mut u8);
    } else {
        out_str(ed, tgoto(ed, s as *mut i8, 0, n) as *mut u8);
    }
}

pub unsafe fn term_fg_color(ed: *mut Editor, n: i32) {
    if *(*decay(&raw mut (*ed).term_strings).wrapping_add(55)) != 0 {
        term_color(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(55), n);
    } else if *(*decay(&raw mut (*ed).term_strings).wrapping_add(50)) != 0 {
        term_color(ed, *decay(&raw mut (*ed).term_strings).wrapping_add(50), n);
    }
}

